// 1. Safely extract the HTML string from the nested output structure
const incomingData = $input.first().json;
const htmlContent = incomingData.output?.html || incomingData.html || "<h1>No HTML provided</h1>";

// 2. Convert the HTML string into a Buffer
const binaryBuffer = Buffer.from(htmlContent, 'utf-8');

// 3. Return the item with the file attached in the binary property
return [
  {
    json: {
      success: true,
      message: "HTML file generated successfully"
    },
    binary: {
      data: {
        data: binaryBuffer.toString('base64'),
        mimeType: 'text/html',
        fileName: 'linkedin-report.html'
      }
    }
  }
];

// Retrieve the persistent global state
const staticData = $getWorkflowStaticData('global');

return $input.all().map(item => {
  const text = $('Telegram Trigger').first().json.message.text || "";
  // Isolate the specific user via their Telegram Chat ID
  const chatId = item.json.message?.chat?.id || "default_user";

  // 1. Initialize memory for this specific user if it's their first time
  if (!staticData[chatId]) {
    staticData[chatId] = { status: "AWAITING_URL" };
  }

  // 2. Look for a LinkedIn URL in the user's message
  const match = text.match(/(?:https?:\/\/)?(?:www\.)?linkedin\.com\/[^\s]+/i);
  let route = "";

  // 3. Routing Logic
  if (text.trim() === "/reset") {
    // Revert the user's state back to asking for a URL
    staticData[chatId].status = "AWAITING_URL";
    route = "ASK_FOR_URL";
  }
  else if (match) {
    // User provided a valid URL. Update their status so they aren't asked again.
    staticData[chatId].status = "DATA_READY"; 
    route = "RUN_APIFY"; 
  } 
  else if (staticData[chatId].status === "DATA_READY") {
    // User already provided a URL previously. This is a follow-up question.
    route = "ANSWER_QUESTION"; 
  } 
  else {
    // User sent text, but hasn't provided a URL yet.
    route = "ASK_FOR_URL"; 
  }

  return {
    json: {
      chatId: chatId,
      text: text,
      route: route,
      url: match ? match[0] : null
    }
  };
});

// Extract the JSON data from all incoming Apify items
const allPosts = $input.all().map(item => item.json);

// Return exactly ONE item. 
// This completely stops the AI Agent from looping.
return [
  {
    json: {
      posts: allPosts
    }
  }
];

